package main

import (
	"context"
	"log"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/mohebro/task-manager-backend/internal/config"
	"github.com/mohebro/task-manager-backend/internal/handler"
	"github.com/mohebro/task-manager-backend/internal/repository"
	"github.com/mohebro/task-manager-backend/internal/router"
	"github.com/mohebro/task-manager-backend/internal/service"

	// Generated by `swag init`. Never edit by hand.
	// Named (not blank) import: main overrides docs.SwaggerInfo.Host
	// at runtime when SWAGGER_HOST is set.
	"github.com/mohebro/task-manager-backend/docs"
)

// @title Task Manager API
// @version 0.1.0
// @description Team task manager backend: auth first, tasks next.
// @host localhost:8080
// @BasePath /
//
// @securityDefinitions.apikey BearerAuth
// @in header
// @name Authorization
// @description How to use it: 1) call POST /auth/register or /auth/login and copy the token. 2) Click the Authorize button at the top of this page. 3) Enter: Bearer <your-token> — the word Bearer, a space, then the token. Just the token alone does NOT work, the server answers 401. 4) Try GET /auth/me.
func main() {
	cfg, err := config.Load()
	if err != nil {
		log.Fatalf("config: %v", err)
	}

	// Annotations are read at generation time (`swag init`), so they
	// cannot see .env. The generated docs package exposes SwaggerInfo,
	// and this override is the runtime bridge: SWAGGER_HOST wins over
	// the @host baked into docs/ (localhost:8080).
	if cfg.SwaggerHost != "" {
		docs.SwaggerInfo.Host = cfg.SwaggerHost
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	pool, err := pgxpool.New(ctx, cfg.DatabaseURL)
	if err != nil {
		log.Fatalf("db: %v", err)
	}
	defer pool.Close()
	if err := pool.Ping(ctx); err != nil {
		log.Fatalf("db ping: %v", err)
	}

	users := repository.NewPostgresUserRepository(pool)
	authService := service.NewAuthService(users, cfg.JWTSecret, cfg.JWTTTL)
	authHandler := handler.NewAuthHandler(authService, users)

	engine := router.New(authHandler)
	log.Printf("listening on :%s", cfg.HTTPPort)
	if err := engine.Run(":" + cfg.HTTPPort); err != nil {
		log.Fatalf("server: %v", err)
	}
}
